using System.Reflection;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using HarmonyLib;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private static string TaskCleanupCardText(CardModel card)
    {
        var text = new StringBuilder();
        typeof(ContinuationStamp).GetMethod("AppendCard", BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, new object[] { text, card, false });
        return text.ToString();
    }

    private static Delegate[] TaskCleanupObservers(CardModel card, string name)
        => ((Delegate?)typeof(CardModel).GetField(name, BindingFlags.Instance | BindingFlags.NonPublic)!
            .GetValue(card))?.GetInvocationList() ?? Array.Empty<Delegate>();

    private static void TaskSeedCleanup(CardModel card)
    {
        card.EnergyCost.SetThisCombat(3);
        card.EnergyCost.SetUntilPlayed(2);
        card.EnergyCost.SetThisTurn(0);
        card.SetStarCostThisCombat(2);
        card.SetStarCostUntilPlayed(4);
        card.SetStarCostThisTurn(0);
        card.ExhaustOnNextPlay = true;
        card.GiveSingleTurnRetain();
        card.GiveSingleTurnSly();
    }

    private Task RunTaskExhaustCleanupAsync(CombatState live, Player player)
    {
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        CombatPredictionSimulator parent = root.ForkSimulator();
        string State(CombatPredictionSimulator simulator) => ContinuationStamp.CapturePredicted(player,
            simulator, ((SimulatedCombatState)simulator.State.CombatState).GetPlayerTurnNumber(player),
            root.Forecast, root.StartTurnNumber).StateText + "\nHISTORY=" + CardContinuationContractHistoryText(simulator);
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        string originalParent = State(parent);
        CardModel Make(CardModel canonical)
        {
            var card = (CardModel)canonical.MutableClone();
            card.Owner = player;
            TaskSeedCleanup(card);
            return card;
        }
        var a = Make(ModelDb.Card<DefendSilent>());
        var b = Make(ModelDb.Card<StrikeSilent>());
        var reversedA = Make(ModelDb.Card<DefendSilent>());
        var reversedB = Make(ModelDb.Card<StrikeSilent>());
        string Pair(CardModel first, CardModel second) => TaskCleanupCardText(first) + "\n" + TaskCleanupCardText(second);
        if (Pair(a, b) != Pair(reversedA, reversedB)) throw new InvalidOperationException("Native pair inputs differ.");
        if (new[] { a, b, reversedA, reversedB }.Any(card =>
            TaskCleanupObservers(card, "EnergyCostChanged").Length != 0
            || TaskCleanupObservers(card, "StarCostChanged").Length != 0))
            throw new InvalidOperationException("Detached native pair has unexpected cleanup observers.");
        var simA = PredictionUtils.CloneCardStateForSimulation(a);
        var simB = PredictionUtils.CloneCardStateForSimulation(b);
        a.EndOfTurnCleanup();
        b.EndOfTurnCleanup();
        reversedB.EndOfTurnCleanup();
        reversedA.EndOfTurnCleanup();
        using (SimulationNotificationIsolation.Enter())
        {
            simB.EndOfTurnCleanup();
            simA.EndOfTurnCleanup();
        }
        string nativeForward = Pair(a, b), nativeReverse = Pair(reversedA, reversedB);
        string simulatedReverse = Pair(simA, simB);
        if (nativeForward != nativeReverse || nativeForward != simulatedReverse)
            throw new InvalidOperationException("No-observer cleanup pair is not equivalent.");
        if (new[] { a, b, simA, simB }.Any(card => card.EnergyCost._localModifiers.Count != 2
            || card._temporaryStarCosts.Count != 2 || PredictionUtils.NeedsEndOfTurnCleanup(card)))
            throw new InvalidOperationException("Cleanup removed persistent/until-played layers or left a turn layer.");

        var unknownA = Make(ModelDb.Card<DefendSilent>());
        var unknownB = Make(ModelDb.Card<StrikeSilent>());
        var unknownReverseA = Make(ModelDb.Card<DefendSilent>());
        var unknownReverseB = Make(ModelDb.Card<StrikeSilent>());
        unknownA.EnergyCostChanged += () => unknownB.EnergyCost.SetThisTurn(0);
        unknownReverseA.EnergyCostChanged += () => unknownReverseB.EnergyCost.SetThisTurn(0);
        bool forwardRejected = TaskCleanupObservers(unknownA, "EnergyCostChanged").Length != 0;
        bool reverseRejected = TaskCleanupObservers(unknownReverseA, "EnergyCostChanged").Length != 0;
        if (!forwardRejected || !reverseRejected) throw new InvalidOperationException("Unknown cross-card observer was missed.");
        var observerClone = PredictionUtils.CloneCardStateForSimulation(unknownA);
        if (TaskCleanupObservers(observerClone, "EnergyCostChanged").Length != 0
            || TaskCleanupObservers(unknownA, "EnergyCostChanged").Length != 1)
            throw new InvalidOperationException("Simulation clone retained a callback or mutated its source registration.");
        unknownA.EndOfTurnCleanup();
        unknownB.EndOfTurnCleanup();
        unknownReverseB.EndOfTurnCleanup();
        unknownReverseA.EndOfTurnCleanup();
        string unknownForward = Pair(unknownA, unknownB), unknownReverse = Pair(unknownReverseA, unknownReverseB);
        if (unknownForward == unknownReverse || unknownB.EnergyCost._localModifiers.Count != 2
            || unknownReverseB.EnergyCost._localModifiers.Count != 3)
            throw new InvalidOperationException("Unknown cross-card observer did not make cleanup order observable.");

        PredictedCard[] targets = parent.State.GetPlayerCombatState(player).AllCards.Take(2).ToArray();
        if (targets.Length != 2) throw new InvalidOperationException("Missing actual-root card pair.");
        foreach (PredictedCard target in targets) TaskSeedCleanup(target.MutablePreview);
        string seededParent = State(parent);
        CombatPredictionSimulator expected = parent.Fork();
        using (SimulationNotificationIsolation.Enter())
            foreach (PredictedCard target in targets)
                expected.State.FindCard(target.Original)!.MutablePreview.EndOfTurnCleanup();
        string expectedState = State(expected);
        var children = Enumerable.Range(0, 16).Select(_ => parent.Fork()).ToArray();
        string[] childInitial = children.Select(State).ToArray();
        if (childInitial.Any(text => text != seededParent)) throw new InvalidOperationException("Initial Fork state differs.");
        var parallelResults = Task.WhenAll(children.Select((child, index) => Task.Run(() =>
        {
            using (SimulationNotificationIsolation.Enter())
            {
                foreach (PredictedCard target in targets)
                {
                    CardModel card = child.State.FindCard(target.Original)!.MutablePreview;
                    card.EnergyCost.SetThisTurn(5 + index);
                    card.SetStarCostThisTurn(6 + index);
                }
                var grandchild = child.Fork();
                string grandchildSeed = State(grandchild), childSeed = State(child);
                if (grandchildSeed != childSeed) throw new InvalidOperationException("Second generation lost cost state.");
                foreach (PredictedCard target in targets.Reverse())
                    child.State.FindCard(target.Original)!.MutablePreview.EndOfTurnCleanup();
                if (State(grandchild) != grandchildSeed)
                    throw new InvalidOperationException("Child cleanup mutated its second generation.");
                foreach (PredictedCard target in targets)
                    grandchild.State.FindCard(target.Original)!.MutablePreview.EndOfTurnCleanup();
                string childState = State(child), grandchildState = State(grandchild);
                if (childState != expectedState || grandchildState != expectedState)
                    throw new InvalidOperationException("Fork cleanup changed full state/history/RNG.");
                return new { index, childMatches = true, grandchildMatches = true,
                    secondGenerationIsolatedBeforeCleanup = true };
            }
        }))).GetAwaiter().GetResult();
        if (State(parent) != seededParent || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
            throw new InvalidOperationException("Cleanup contract mutated its parent/live.");

        var cleanupMethods = new[] {
            typeof(CardModel).GetMethod(nameof(CardModel.EndOfTurnCleanup))!,
            typeof(CardEnergyCost).GetMethod(nameof(CardEnergyCost.EndOfTurnCleanup))!,
            typeof(CardModel).GetMethod(nameof(CardModel.SetStarCostThisTurn))! };
        object[] methodIdentities = cleanupMethods.Select(method =>
        {
            Patches? patches = Harmony.GetPatchInfo(method);
            object Describe(Patch patch) => new { declaringType = patch.PatchMethod.DeclaringType!.FullName,
                signature = patch.PatchMethod.ToString(), owner = patch.owner, priority = patch.priority,
                before = patch.before, after = patch.after, index = patch.index,
                mvid = patch.PatchMethod.Module.ModuleVersionId.ToString(), token = patch.PatchMethod.MetadataToken,
                ilSha256 = Convert.ToHexString(SHA256.HashData(patch.PatchMethod.GetMethodBody()!.GetILAsByteArray()!)) };
            return (object)new { declaringType = method.DeclaringType!.FullName, signature = method.ToString(),
                mvid = method.Module.ModuleVersionId.ToString(), token = method.MetadataToken,
                ilSha256 = Convert.ToHexString(SHA256.HashData(method.GetMethodBody()!.GetILAsByteArray()!)),
                prefixes = patches?.Prefixes.Select(Describe).ToArray() ?? Array.Empty<object>(),
                postfixes = patches?.Postfixes.Select(Describe).ToArray() ?? Array.Empty<object>(),
                transpilers = patches?.Transpilers.Select(Describe).ToArray() ?? Array.Empty<object>(),
                finalizers = patches?.Finalizers.Select(Describe).ToArray() ?? Array.Empty<object>() };
        }).ToArray();
        _completedChecks.Add("CleanupOrder:NativePairVsReverseVsSimulation:PersistentAndUntilPlayedLayersPreserved:CrossCardObserverCounterexample:UnknownObserverComponentRejected:CloneObserverIsolation:16ParallelChildrenSecondGeneration:FullStampRichHistoryNineRngParentLive");
        _completedChecks.Add("TASK_EXHAUST_CLEANUP " + JsonSerializer.Serialize(new {
            nativeForward, nativeReverse, simulatedReverse, unknownForward, unknownReverse,
            forwardRejected, reverseRejected, observerCloneCallbacks = 0, sourceCallbacks = 1,
            parallelResults, methodIdentities, originalParentSha256 = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(originalParent))),
            seededParentSha256 = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(seededParent))),
            expectedStateSha256 = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(expectedState))),
            liveUnchanged = true, actualPrunes = 0, isWholeOrderCertificate = false,
            isActualEndTurnTest = false, nativeDetachedPairOnly = true }));
        return Task.CompletedTask;
    }
}

